import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Drawer","description":"","frontmatter":{},"headers":[],"relativePath":"components/drawer.md","filePath":"components/drawer.md"}'),d={name:"components/drawer.md"};function s(n,e,i,h,c,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="drawer" tabindex="-1">Drawer <a class="header-anchor" href="#drawer" aria-label="Permalink to &quot;Drawer&quot;">​</a></h1><p>Drawer is a panel that slides in from the left over a narrow screen.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for the navigation or the list that sits in a column at the left on a wide screen, when the screen is too narrow to show that column. Its content is the column&#39;s content: list items, and text in a <a href="./block">Block</a>. A panel that sits beside the stage on a wide screen becomes a <a href="./sheet">Sheet</a> instead.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>false</code></td><td>Whether it is open (bindable)</td></tr><tr><td><code>label</code></td><td></td><td>The accessible name of the drawer</td></tr><tr><td><code>onclose</code></td><td></td><td>Called when the scrim or Escape closes it</td></tr><tr><td><code>children</code></td><td>required</td><td>The content</td></tr><tr><td><code>inline</code></td><td><code>false</code></td><td>The same surface in the flow, for documentation</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>It is placed absolutely at the left of its frame, which must be a positioned element, over its full height. Its width is <code>--kata-width-drawer</code>, never wider than the frame; it has the panel surface, a strong line on its right and no padding, and it scrolls when its content is taller. A scrim covers the rest of the frame; a press on the scrim or Escape closes the drawer. Both are on the sheet layer. The scrim&#39;s name is the <code>close</code> message.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/drawer/" title="Drawer" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/drawer/" target="_blank" rel="noopener">Drawer</a></figcaption></figure>',10)])])}const f=t(d,[["render",s]]);export{m as __pageData,f as default};
